{"command":"cat <<'EOF' > main.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <unistd.h>
#include <curses.h>
#include <locale.h>
#include <time.h>
#include <ctype.h>
#include <limits.h>

#define MAX_CONTEXTS 8

typedef struct {
    char name[NAME_MAX];
    struct stat st;
    int is_dir;
    char suffix;
    char link_target[PATH_MAX];
} FileEntry;

typedef struct {
    char path[PATH_MAX];
    int cursor;
    int scroll;
    FileEntry *entries;
    int num_entries;
    int active;
} Context;

Context contexts[MAX_CONTEXTS];
int current_context = 0;
int detail_mode = 0;

void format_size(off_t size, char *buf) {
    if (size < 1024) {
        sprintf(buf, "%ldB", size);
    } else {
        double d = size / 1024.0;
        const char *units[] = {"K", "M", "G", "T", "P"};
        int i = 0;
        while (d >= 1024 && i < 4) {
            d /= 1024.0;
            i++;
        }
        if (d < 10 && (d - (int)d) > 0.05) {
            sprintf(buf, "%.1f%s", d, units[i]);
        } else {
            sprintf(buf, "%.0f%s", d, units[i]);
        }
    }
}

int compare_entries(const void *a, const void *b) {
    FileEntry *fa = (FileEntry *)a;
    FileEntry *fb = (FileEntry *)b;
    if (fa->is_dir != fb->is_dir) return fb->is_dir - fa->is_dir;
    if (isdigit(fa->name[0]) && isdigit(fb->name[0])) {
        char *sa, *sb;
        long long na = strtoll(fa->name, &sa, 10);
        long long nb = strtoll(fb->name, &sb, 10);
        if (na != nb) return (na < nb) ? -1 : 1;
        return strcmp(sa, sb);
    }
    if (isdigit(fa->name[0])) return -1;
    if (isdigit(fb->name[0])) return 1;
    return strcmp(fa->name, fb->name);
}

void load_dir(int ctx_idx) {
    Context *ctx = &contexts[ctx_idx];
    for (int i = 0; i < ctx->num_entries; i++) {
        // free(ctx->entries[i].name); // Not dynamic for now
    }
    free(ctx->entries);
    ctx->entries = NULL;
    ctx->num_entries = 0;

    DIR *dir = opendir(ctx->path);
    if (!dir) return;

    struct dirent *entry;
    int cap = 16;
    ctx->entries = malloc(cap * sizeof(FileEntry));

    while ((entry = readdir(dir))) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;

        if (ctx->num_entries >= cap) {
            cap *= 2;
            ctx->entries = realloc(ctx->entries, cap * sizeof(FileEntry));
        }

        FileEntry *fe = &ctx->entries[ctx->num_entries];
        strncpy(fe->name, entry->d_name, NAME_MAX);

        char full_path[PATH_MAX];
        snprintf(full_path, PATH_MAX, "%s/%s", ctx->path, entry->d_name);

        if (lstat(full_path, &fe->st) != 0) continue;

        fe->is_dir = S_ISDIR(fe->st.st_mode);
        fe->suffix = '\0';
        fe->link_target[0] = '\0';

        if (S_ISLNK(fe->st.st_mode)) {
            struct stat st_link;
            if (stat(full_path, &st_link) == 0 && S_ISDIR(st_link.st_mode)) {
                fe->is_dir = 1;
                fe->suffix = '/';
            } else {
                fe->suffix = '@';
            }
            readlink(full_path, fe->link_target, PATH_MAX - 1);
        } else if (S_ISDIR(fe->st.st_mode)) {
            fe->suffix = '/';
        } else if (fe->st.st_mode & S_IXUSR) {
            fe->suffix = '*';
        }

        ctx->num_entries++;
    }
    closedir(dir);
    qsort(ctx->entries, ctx->num_entries, sizeof(FileEntry), compare_entries);
}

void draw() {
    clear();
    Context *ctx = &contexts[current_context];

    // Top bar
    for (int i = 0; i < MAX_CONTEXTS; i++) {
        if (i == current_context) attron(A_REVERSE);
        printw("%d ", i + 1);
        if (i == current_context) attroff(A_REVERSE);
    }
    printw("%s\n\n", ctx->path);

    int rows, cols;
    getmaxyx(stdscr, rows, cols);
    int list_height = rows - 4;

    for (int i = 0; i < list_height && (i + ctx->scroll) < ctx->num_entries; i++) {
        int idx = i + ctx->scroll;
        FileEntry *fe = &ctx->entries[idx];

        if (idx == ctx->cursor) attron(A_REVERSE);

        if (detail_mode) {
            char time_buf[20];
            struct tm *tm = localtime(&fe->st.st_mtime);
            strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M", tm);

            char size_buf[16];
            format_size(fe->st.st_size, size_buf);

            if (idx == ctx->cursor) mvprintw(i + 2, 0, ">%s  %o %8s  %s%c", time_buf, fe->st.st_mode & 0777, size_buf, fe->name, fe->suffix);
            else mvprintw(i + 2, 1, "%s  %o %8s  %s%c", time_buf, fe->st.st_mode & 0777, size_buf, fe->name, fe->suffix);
        } else {
            mvprintw(i + 2, 1, "%s%c", fe->name, fe->suffix);
        }

        if (idx == ctx->cursor) attroff(A_REVERSE);
    }

    // Bottom bar
    if (ctx->num_entries > 0) {
        FileEntry *fe = &ctx->entries[ctx->cursor];
        char time_buf[20];
        struct tm *tm = localtime(&fe->st.st_mtime);
        strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M", tm);

        char size_buf[16];
        format_size(fe->st.st_size, size_buf);

        char perms[11];
        mode_t m = fe->st.st_mode;
        perms[0] = S_ISDIR(m) ? 'd' : (S_ISLNK(m) ? 'l' : '-');
        perms[1] = (m & S_IRUSR) ? 'r' : '-';
        perms[2] = (m & S_IWUSR) ? 'w' : '-';
        perms[3] = (m & S_IXUSR) ? 'x' : '-';
        perms[4] = (m & S_IRGRP) ? 'r' : '-';
        perms[5] = (m & S_IWGRP) ? 'w' : '-';
        perms[6] = (m & S_IXGRP) ? 'x' : '-';
        perms[7] = (m & S_IROTH) ? 'r' : '-';
        perms[8] = (m & S_IWOTH) ? 'w' : '-';
        perms[9] = (m & S_IXOTH) ? 'x' : '-';
        perms[10] = '\0';

        mvprintw(rows - 1, 0, "%d/%d  %s %s %s", ctx->cursor + 1, ctx->num_entries, time_buf, perms, size_buf);
        if (S_ISLNK(fe->st.st_mode)) {
            printw(" ->%s", fe->link_target);
        }
    }

    refresh();
}

int main(int argc, char *argv[]) {
    setlocale(LC_ALL, "");
    initscr();
    raw();
    keypad(stdscr, TRUE);
    noecho();
    curs_set(0);

    for (int i = 0; i < MAX_CONTEXTS; i++) {
        getcwd(contexts[i].path, PATH_MAX);
        contexts[i].active = (i == 0);
    }

    char *start_path = ".";
    if (argc > 1) start_path = argv[1];
    realpath(start_path, contexts[0].path);
    load_dir(0);

    while (1) {
        draw();
        int ch = getch();
        Context *ctx = &contexts[current_context];

        if (ch == 'q') break;
        else if (ch == KEY_DOWN || ch == 'j') {
            if (ctx->cursor < ctx->num_entries - 1) ctx->cursor++;
        } else if (ch == KEY_UP || ch == 'k') {
            if (ctx->cursor > 0) ctx->cursor--;
        } else if (ch == KEY_RIGHT || ch == 'l' || ch == 10) {
            if (ctx->num_entries > 0 && ctx->entries[ctx->cursor].is_dir) {
                strcat(ctx->path, "/");
                strcat(ctx->path, ctx->entries[ctx->cursor].name);
                char actual_path[PATH_MAX];
                realpath(ctx->path, actual_path);
                strcpy(ctx->path, actual_path);
                ctx->cursor = 0;
                ctx->scroll = 0;
                load_dir(current_context);
            }
        } else if (ch == KEY_LEFT || ch == 'h' || ch == KEY_BACKSPACE || ch == 127) {
            char *last_slash = strrchr(ctx->path, '/');
            if (last_slash && last_slash != ctx->path) {
                *last_slash = '\0';
                load_dir(current_context);
                ctx->cursor = 0;
                ctx->scroll = 0;
            } else if (last_slash == ctx->path) {
                strcpy(ctx->path, "/");
                load_dir(current_context);
                ctx->cursor = 0;
                ctx->scroll = 0;
            }
        } else if (ch == '\t') {
            current_context = (current_context + 1) % MAX_CONTEXTS;
            if (!contexts[current_context].active) {
                strcpy(contexts[current_context].path, contexts[0].path); // Default to context 1's path
                contexts[current_context].active = 1;
            }
            load_dir(current_context);
        } else if (ch == 'd') {
            detail_mode = !detail_mode;
        }
    }

    endwin();
    return 0;
}
EOF
"}

