#include <limits.h>
#include <sys/ioctl.h>

#define MAX_CONTEXTS 8

typedef struct {
    char name[NAME_MAX];
    struct stat st;
    int is_dir;
    char suffix;
    char link_target[PATH_MAX];
} FileEntry;

typedef struct {
    char path[PATH_MAX];
    int cursor;
    int scroll;
    FileEntry *entries;
    int num_entries;
    int *filtered_indices;
    int num_filtered;
    int active;
} Context;

Context contexts[MAX_CONTEXTS];
int current_context = 0;
int detail_mode = 0;
char filter_str[256] = "";
int filter_mode = 0;
struct termios orig_termios;

void disableRawMode() {
    tcsetattr(STDIN_FILENO, TCSAFLUSH, &orig_termios);
    printf("\033[?25h\033[0m\033[2J\033[H");
}

void enableRawMode() {
    tcgetattr(STDIN_FILENO, &orig_termios);
    atexit(disableRawMode);
    struct termios raw = orig_termios;
    raw.c_lflag &= ~(ECHO | ICANON | ISIG | IEXTEN);
    raw.c_iflag &= ~(BRKINT | ICRNL | INPCK | ISTRIP | IXON);
    raw.c_cflag |= (CS8);
    raw.c_oflag &= ~(OPOST);
    tcsetattr(STDIN_FILENO, TCSAFLUSH, &raw);
    printf("\033[?25l");
}

int compare_entries(const void *a, const void *b) {
    FileEntry *fa = (FileEntry *)a;
    FileEntry *fb = (FileEntry *)b;
    if (fa->is_dir != fb->is_dir) return fb->is_dir - fa->is_dir;
    const char *s1 = fa->name;
    const char *s2 = fb->name;
    if (isdigit(s1[0]) && isdigit(s2[0])) {
        char *end1, *end2;
        long long n1 = strtoll(s1, &end1, 10);
        long long n2 = strtoll(s2, &end2, 10);
        if (n1 != n2) return (n1 < n2) ? -1 : 1;
        s1 = end1; s2 = end2;
    } else if (isdigit(s1[0])) return -1;
    else if (isdigit(s2[0])) return 1;
    return strcmp(s1, s2);
}

void format_size(off_t size, char *buf) {
    if (size < 1024) sprintf(buf, "%ldB", size);
    else {
        double d = size / 1024.0;
        const char *units[] = {"K", "M", "G", "T", "P"};
        int i = 0;
        while (d >= 1024 && i < 4) { d /= 1024.0; i++; }
        if (d < 100 && (d - (int)d) >= 0.05) sprintf(buf, "%.1f%s", d, units[i]);
        else sprintf(buf, "%.0f%s", d, units[i]);
    }
}

void update_filter(int ctx_idx) {
    Context *ctx = &contexts[ctx_idx];
    ctx->num_filtered = 0;
    for (int i = 0; i < ctx->num_entries; i++) {
        if (filter_str[0] == '\0' || strcasestr(ctx->entries[i].name, filter_str)) {
            ctx->filtered_indices[ctx->num_filtered++] = i;
        }
    }
    if (ctx->cursor >= ctx->num_filtered) ctx->cursor = ctx->num_filtered > 0 ? ctx->num_filtered - 1 : 0;
}

void load_dir(int ctx_idx) {
    Context *ctx = &contexts[ctx_idx];
    free(ctx->entries); free(ctx->filtered_indices);
    ctx->entries = NULL; ctx->filtered_indices = NULL; ctx->num_entries = 0;
    DIR *dir = opendir(ctx->path);
    if (!dir) return;
    int cap = 16;
    ctx->entries = malloc(cap * sizeof(FileEntry));
    struct dirent *entry;
    while ((entry = readdir(dir))) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;
        if (ctx->num_entries >= cap) { cap *= 2; ctx->entries = realloc(ctx->entries, cap * sizeof(FileEntry)); }
        FileEntry *fe = &ctx->entries[ctx->num_entries];
        strncpy(fe->name, entry->d_name, NAME_MAX);
        char full_path[PATH_MAX]; snprintf(full_path, PATH_MAX, "%s/%s", ctx->path, entry->d_name);
        if (lstat(full_path, &fe->st) != 0) continue;
        fe->is_dir = S_ISDIR(fe->st.st_mode); fe->suffix = '\0'; fe->link_target[0] = '\0';
        if (S_ISLNK(fe->st.st_mode)) {
            struct stat st_link;
            if (stat(full_path, &st_link) == 0 && S_ISDIR(st_link.st_mode)) { fe->is_dir = 1; fe->suffix = '/'; }
            else fe->suffix = '@';
            readlink(full_path, fe->link_target, PATH_MAX - 1);
        } else if (S_ISDIR(fe->st.st_mode)) fe->suffix = '/';
        else if (fe->st.st_mode & S_IXUSR) fe->suffix = '*';
        ctx->num_entries++;
    }
    closedir(dir);
    qsort(ctx->entries, ctx->num_entries, sizeof(FileEntry), compare_entries);
    ctx->filtered_indices = malloc(ctx->num_entries * sizeof(int));
    update_filter(ctx_idx);
}

void draw() {
    struct winsize w; ioctl(STDOUT_FILENO, TIOCGWINSZ, &w);
    printf("\033[H\033[J");
    Context *ctx = &contexts[current_context];
    for (int i = 0; i < MAX_CONTEXTS; i++) {
        if (i == current_context) printf("\033[7m%d\033[0m ", i + 1);
        else printf("%d ", i + 1);
    }
    printf("%s\n\n", ctx->path);
    int list_height = w.ws_row - 4;
    if (ctx->cursor >= ctx->scroll + list_height) ctx->scroll = ctx->cursor - list_height + 1;
    if (ctx->cursor < ctx->scroll) ctx->scroll = ctx->cursor;
    for (int i = 0; i < list_height && (i + ctx->scroll) < ctx->num_filtered; i++) {
        int idx = ctx->filtered_indices[i + ctx->scroll];
        FileEntry *fe = &ctx->entries[idx];
        if (i + ctx->scroll == ctx->cursor) printf("\033[7m");
        if (detail_mode) {
            char t_buf[20]; strftime(t_buf, 20, "%Y-%m-%d %H:%M", localtime(&fe->st.st_mtime));
            char s_buf[16]; format_size(fe->st.st_size, s_buf);
            if (i + ctx->scroll == ctx->cursor) printf(">%s  %o %8s  %s%c", t_buf, fe->st.st_mode & 0777, s_buf, fe->name, fe->suffix);
            else printf(" %s  %o %8s  %s%c", t_buf, fe->st.st_mode & 0777, s_buf, fe->name, fe->suffix);
        } else printf(" %s%c", fe->name, fe->suffix);
        if (i + ctx->scroll == ctx->cursor) printf("\033[0m");
        printf("\n");
    }
    printf("\033[%d;1H", w.ws_row);
    if (filter_mode) printf("/%s", filter_str);
    else if (ctx->num_filtered > 0) {
        int idx = ctx->filtered_indices[ctx->cursor];
        FileEntry *fe = &ctx->entries[idx];
        char t_buf[20]; strftime(t_buf, 20, "%Y-%m-%d %H:%M", localtime(&fe->st.st_mtime));
        char s_buf[16]; format_size(fe->st.st_size, s_buf);
        char p[11]; mode_t m = fe->st.st_mode;
        p[0] = S_ISDIR(m) ? 'd' : (S_ISLNK(m) ? 'l' : '-');
        p[1] = (m & S_IRUSR) ? 'r' : '-'; p[2] = (m & S_IWUSR) ? 'w' : '-'; p[3] = (m & S_IXUSR) ? 'x' : '-';
        p[4] = (m & S_IRGRP) ? 'r' : '-'; p[5] = (m & S_IWGRP) ? 'w' : '-'; p[6] = (m & S_IXGRP) ? 'x' : '-';
        p[7] = (m & S_IROTH) ? 'r' : '-'; p[8] = (m & S_IWOTH) ? 'w' : '-'; p[9] = (m & S_IXOTH) ? 'x' : '-'; p[10] = '\0';
        printf("%d/%d  %s %s %8s", ctx->cursor + 1, ctx->num_filtered, t_buf, p, s_buf);
        if (S_ISLNK(fe->st.st_mode)) printf(" ->%s", fe->link_target);
    }
    fflush(stdout);
}

int main(int argc, char *argv[]) {
    if (argc > 1 && strcmp(argv[1], "-V") == 0) { printf("5.2\n"); return 0; }
    if (argc > 1 && strcmp(argv[1], "-h") == 0) {
        printf("usage: nnn [OPTIONS] [PATH]\n\n... (rest of help output) ...\n");
        return 0;
    }
    enableRawMode();
    char start_path[PATH_MAX]; getcwd(start_path, PATH_MAX);
    if (argc > 1 && argv[1][0] != '-') realpath(argv[1], start_path);
    for (int i = 0; i < MAX_CONTEXTS; i++) { strcpy(contexts[i].path, start_path); contexts[i].active = (i == 0); }
    load_dir(0);
    while (1) {
        draw();
        unsigned char c; if (read(STDIN_FILENO, &c, 1) != 1) break;
        Context *ctx = &contexts[current_context];
        if (filter_mode) {
            if (c == 27) { filter_mode = 0; filter_str[0] = '\0'; update_filter(current_context); }
            else if (c == 10 || c == 13) { filter_mode = 0; }
            else if (c == 127 || c == 8) { if (strlen(filter_str) > 0) filter_str[strlen(filter_str) - 1] = '\0'; update_filter(current_context); }
            else if (isprint(c)) { strncat(filter_str, (char *)&c, 1); update_filter(current_context); 
                if (ctx->num_filtered == 1 && ctx->entries[ctx->filtered_indices[0]].is_dir) {
                    strcat(ctx->path, "/"); strcat(ctx->path, ctx->entries[ctx->filtered_indices[0]].name);
                    char actual[PATH_MAX]; realpath(ctx->path, actual); strcpy(ctx->path, actual);
                    filter_mode = 0; filter_str[0] = '\0'; ctx->cursor = 0; ctx->scroll = 0; load_dir(current_context);
                }
            }
            continue;
        }
        if (c == 'q') break;
        else if (c == 'j' || c == 66) { if (ctx->cursor < ctx->num_filtered - 1) ctx->cursor++; }
        else if (c == 'k' || c == 65) { if (ctx->cursor > 0) ctx->cursor--; }
        else if (c == 'l' || c == 10 || c == 13 || c == 67) {
            if (ctx->num_filtered > 0 && ctx->entries[ctx->filtered_indices[ctx->cursor]].is_dir) {
                strcat(ctx->path, "/"); strcat(ctx->path, ctx->entries[ctx->filtered_indices[ctx->cursor]].name);
                char actual[PATH_MAX]; realpath(ctx->path, actual); strcpy(ctx->path, actual);
                ctx->cursor = 0; ctx->scroll = 0; load_dir(current_context);
            }
        } else if (c == 'h' || c == 127 || c == 8 || c == 68) {
            char *last = strrchr(ctx->path, '/');
            if (last && last != ctx->path) { *last = '\0'; load_dir(current_context); ctx->cursor = 0; ctx->scroll = 0; }
            else if (last == ctx->path) { strcpy(ctx->path, "/"); load_dir(current_context); ctx->cursor = 0; ctx->scroll = 0; }
        } else if (c == '\t') {
            current_context = (current_context + 1) % MAX_CONTEXTS;
            if (!contexts[current_context].active) { strcpy(contexts[current_context].path, contexts[0].path); contexts[current_context].active = 1; }
            load_dir(current_context);
        } else if (c == 'd') detail_mode = !detail_mode;
        else if (c == '/') { filter_mode = 1; filter_str[0] = '\0'; }
    }
    return 0;
}
